window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-28faa903722f3280"]={"versions": [{"id": "FIG-28faa903722f3280", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Bit- und Byte-Layout (Protokolldatenstruktur) einer CAN Network Management PDU (NM-PDU) innerhalb des AUTOSAR CAN Network Management (CanNm) Stacks. Das Diagramm spezifiziert die standardisierte 8-Byte-Struktur einer klassischen CAN-NM-Botschaft mit Bitpositionen (Bit 7 bis Bit 0) und Byte-Indizes (Byte 0 bis Byte 7).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte 8-Byte-PDU mit folgenden Feldern über die Bitbreite Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\">\n<li><code>Byte 0</code>: Source Node Identifier (CBV/NID-Position konfigurierbar, hier an Byte 0)</li>\n<li><code>Byte 1</code>: Control Bit Vector (CBV)</li>\n<li><code>Byte 2</code>: User data 0</li>\n<li><code>Byte 3</code>: User data 1</li>\n<li><code>Byte 4</code>: User data 2</li>\n<li><code>Byte 5</code>: User data 3</li>\n<li><code>Byte 6</code>: User data 4</li>\n<li><code>Byte 7</code>: User data 5</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Frame-Struktur-Definition ohne zeitlichen Ablauf. Bei der zyklischen oder ereignisgesteuerten Übertragung im CanNm wird die PDU von Byte 0 bis Byte 7 serialisiert und an das CAN-Interface (CanIf) übergeben; empfangsseitig parst CanNm Source Node Identifier, Control Bit Vector und extrahiert die Nutzdaten-Bytes 0 bis 5 für höhere Schichten (PduR/Com).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Beispiel-Layout für eine 8-Byte CAN-NM-PDU mit aktiviertem Source Node Identifier und Control Bit Vector an den ersten beiden Byte-Positionen (<code>CanNmPduNidPosition = BYTE_0</code>, <code>CanNmPduCbvPosition = BYTE_1</code>). Die verbleibenden Bytes 2 bis 7 stehen vollumfänglich als transparente Nutzdaten (<code>User data 0</code> bis <code>User data 5</code>) zur Verfügung.</p>"}, {"id": "FIG-9968667c45277c6c", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Bit- und Byte-Layout (Protokolldatenstruktur) einer CAN Network Management PDU (NM-PDU) innerhalb des AUTOSAR CAN Network Management (CanNm) Stacks. Das Diagramm spezifiziert die standardisierte 8-Byte-Struktur einer klassischen CAN-NM-Botschaft mit Bitpositionen (Bit 7 bis Bit 0) und Byte-Indizes (Byte 0 bis Byte 7).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte 8-Byte-PDU mit folgenden Feldern über die Bitbreite Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\">\n<li><code>Byte 0</code>: Source Node Identifier (CBV/NID-Position konfigurierbar, hier an Byte 0)</li>\n<li><code>Byte 1</code>: Control Bit Vector (CBV)</li>\n<li><code>Byte 2</code>: User data 0</li>\n<li><code>Byte 3</code>: User data 1</li>\n<li><code>Byte 4</code>: User data 2</li>\n<li><code>Byte 5</code>: User data 3</li>\n<li><code>Byte 6</code>: User data 4</li>\n<li><code>Byte 7</code>: User data 5</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Frame-Struktur-Definition ohne zeitlichen Ablauf. Bei der zyklischen oder ereignisgesteuerten Übertragung im CanNm wird die PDU von Byte 0 bis Byte 7 serialisiert und an das CAN-Interface (CanIf) übergeben; empfangsseitig parst CanNm Source Node Identifier, Control Bit Vector und extrahiert die Nutzdaten-Bytes 0 bis 5 für höhere Schichten (PduR/Com).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Beispiel-Layout für eine 8-Byte CAN-NM-PDU mit aktiviertem Source Node Identifier und Control Bit Vector an den ersten beiden Byte-Positionen (<code>CanNmPduNidPosition = BYTE_0</code>, <code>CanNmPduCbvPosition = BYTE_1</code>). Die verbleibenden Bytes 2 bis 7 stehen vollumfänglich als transparente Nutzdaten (<code>User data 0</code> bis <code>User data 5</code>) zur Verfügung.</p>"}, {"id": "FIG-090714385aa958af", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Bit- und Byte-Layout (Protokolldatenstruktur) einer CAN Network Management PDU (NM-PDU) innerhalb des AUTOSAR CAN Network Management (CanNm) Stacks. Das Diagramm spezifiziert die standardisierte 8-Byte-Struktur einer klassischen CAN-NM-Botschaft mit Bitpositionen (Bit 7 bis Bit 0) und Byte-Indizes (Byte 0 bis Byte 7).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte 8-Byte-PDU mit folgenden Feldern über die Bitbreite Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\">\n<li><code>Byte 0</code>: Source Node Identifier (CBV/NID-Position konfigurierbar, hier an Byte 0)</li>\n<li><code>Byte 1</code>: Control Bit Vector (CBV)</li>\n<li><code>Byte 2</code>: User data 0</li>\n<li><code>Byte 3</code>: User data 1</li>\n<li><code>Byte 4</code>: User data 2</li>\n<li><code>Byte 5</code>: User data 3</li>\n<li><code>Byte 6</code>: User data 4</li>\n<li><code>Byte 7</code>: User data 5</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Frame-Struktur-Definition ohne zeitlichen Ablauf. Bei der zyklischen oder ereignisgesteuerten Übertragung im CanNm wird die PDU von Byte 0 bis Byte 7 serialisiert und an das CAN-Interface (CanIf) übergeben; empfangsseitig parst CanNm Source Node Identifier, Control Bit Vector und extrahiert die Nutzdaten-Bytes 0 bis 5 für höhere Schichten (PduR/Com).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Beispiel-Layout für eine 8-Byte CAN-NM-PDU mit aktiviertem Source Node Identifier und Control Bit Vector an den ersten beiden Byte-Positionen (<code>CanNmPduNidPosition = BYTE_0</code>, <code>CanNmPduCbvPosition = BYTE_1</code>). Die verbleibenden Bytes 2 bis 7 stehen vollumfänglich als transparente Nutzdaten (<code>User data 0</code> bis <code>User data 5</code>) zur Verfügung.</p>"}, {"id": "FIG-13fc0213aa24142b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Bit- und Byte-Layout (Protokolldatenstruktur) einer CAN Network Management PDU (NM-PDU) innerhalb des AUTOSAR CAN Network Management (CanNm) Stacks. Das Diagramm spezifiziert die standardisierte 8-Byte-Struktur einer klassischen CAN-NM-Botschaft mit Bitpositionen (Bit 7 bis Bit 0) und Byte-Indizes (Byte 0 bis Byte 7).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte 8-Byte-PDU mit folgenden Feldern über die Bitbreite Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\">\n<li><code>Byte 0</code>: Source Node Identifier (CBV/NID-Position konfigurierbar, hier an Byte 0)</li>\n<li><code>Byte 1</code>: Control Bit Vector (CBV)</li>\n<li><code>Byte 2</code>: User data 0</li>\n<li><code>Byte 3</code>: User data 1</li>\n<li><code>Byte 4</code>: User data 2</li>\n<li><code>Byte 5</code>: User data 3</li>\n<li><code>Byte 6</code>: User data 4</li>\n<li><code>Byte 7</code>: User data 5</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Frame-Struktur-Definition ohne zeitlichen Ablauf. Bei der zyklischen oder ereignisgesteuerten Übertragung im CanNm wird die PDU von Byte 0 bis Byte 7 serialisiert und an das CAN-Interface (CanIf) übergeben; empfangsseitig parst CanNm Source Node Identifier, Control Bit Vector und extrahiert die Nutzdaten-Bytes 0 bis 5 für höhere Schichten (PduR/Com).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Beispiel-Layout für eine 8-Byte CAN-NM-PDU mit aktiviertem Source Node Identifier und Control Bit Vector an den ersten beiden Byte-Positionen (<code>CanNmPduNidPosition = BYTE_0</code>, <code>CanNmPduCbvPosition = BYTE_1</code>). Die verbleibenden Bytes 2 bis 7 stehen vollumfänglich als transparente Nutzdaten (<code>User data 0</code> bis <code>User data 5</code>) zur Verfügung.</p>"}, {"id": "FIG-04076bc5501d3fc1", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Bit- und Byte-Layout (Protokolldatenstruktur) einer CAN Network Management PDU (NM-PDU) innerhalb des AUTOSAR CAN Network Management (CanNm) Stacks. Das Diagramm spezifiziert die standardisierte 8-Byte-Struktur einer klassischen CAN-NM-Botschaft mit Bitpositionen (Bit 7 bis Bit 0) und Byte-Indizes (Byte 0 bis Byte 7).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte 8-Byte-PDU mit folgenden Feldern über die Bitbreite Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\">\n<li><code>Byte 0</code>: Source Node Identifier (CBV/NID-Position konfigurierbar, hier an Byte 0)</li>\n<li><code>Byte 1</code>: Control Bit Vector (CBV)</li>\n<li><code>Byte 2</code>: User data 0</li>\n<li><code>Byte 3</code>: User data 1</li>\n<li><code>Byte 4</code>: User data 2</li>\n<li><code>Byte 5</code>: User data 3</li>\n<li><code>Byte 6</code>: User data 4</li>\n<li><code>Byte 7</code>: User data 5</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Frame-Struktur-Definition ohne zeitlichen Ablauf. Bei der zyklischen oder ereignisgesteuerten Übertragung im CanNm wird die PDU von Byte 0 bis Byte 7 serialisiert und an das CAN-Interface (CanIf) übergeben; empfangsseitig parst CanNm Source Node Identifier, Control Bit Vector und extrahiert die Nutzdaten-Bytes 0 bis 5 für höhere Schichten (PduR/Com).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Beispiel-Layout für eine 8-Byte CAN-NM-PDU mit aktiviertem Source Node Identifier und Control Bit Vector an den ersten beiden Byte-Positionen (<code>CanNmPduNidPosition = BYTE_0</code>, <code>CanNmPduCbvPosition = BYTE_1</code>). Die verbleibenden Bytes 2 bis 7 stehen vollumfänglich als transparente Nutzdaten (<code>User data 0</code> bis <code>User data 5</code>) zur Verfügung.</p>"}, {"id": "FIG-076c3aa7f24de5b0", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Bit- und Byte-Layout (Protokolldatenstruktur) einer CAN Network Management PDU (NM-PDU) mit Partial Network Cluster (PNC) Unterstützung innerhalb des AUTOSAR CAN Network Management (CanNm) Stacks. Das Diagramm spezifiziert die standardisierte 8-Byte-Struktur einer CAN-NM-Botschaft mit Bitpositionen (Bit 7 bis Bit 0) und Byte-Indizes (Byte 0 bis Byte 7).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte 8-Byte-PDU mit folgenden Feldern über die Bitbreite Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\">\n<li><code>Byte 0</code>: Source Node Identifier</li>\n<li><code>Byte 1</code>: Control Bit Vector (CBV)</li>\n<li><code>Byte 2</code>: User data 0</li>\n<li><code>Byte 3</code>: User data 1</li>\n<li><code>Byte 4</code>: PNC bit vector - byte 0</li>\n<li><code>Byte 5</code>: PNC bit vector - byte 1</li>\n<li><code>Byte 6</code>: PNC bit vector - byte 2</li>\n<li><code>Byte 7</code>: PNC bit vector - byte 3</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Frame-Struktur-Definition ohne zeitlichen Ablauf. Bei der zyklischen oder ereignisgesteuerten Übertragung im CanNm wird die PDU von Byte 0 bis Byte 7 serialisiert und an das CAN-Interface (CanIf) übergeben; empfangsseitig parst CanNm Source Node Identifier, Control Bit Vector und extrahiert die Nutzdaten-Bytes 0 bis 5 für höhere Schichten (PduR/Com).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Beispiel-Layout für eine 8-Byte CAN-NM-PDU mit Partial-Networking-Unterstützung (<code>CanNmPnEnabled = TRUE</code>). <code>Byte 0</code> enthält den Source Node Identifier, <code>Byte 1</code> den Control Bit Vector. <code>Byte 2</code> und <code>Byte 3</code> transportieren frei verfügbare Anwenderdaten (<code>User data 0</code> und <code>User data 1</code>), während <code>Byte 4</code> bis <code>Byte 7</code> für den Partial Network Cluster Bit-Vektor (<code>PNC bit vector - byte 0</code> bis <code>byte 3</code>) zur selektiven Aktivierung/Deaktivierung von Teilnetzen reserviert sind.</p>"}, {"id": "FIG-652be64e8790d9a2", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Bit- und Byte-Layout (Protokolldatenstruktur) einer CAN Network Management PDU (NM-PDU) mit Partial Network Cluster (PNC) Unterstützung innerhalb des AUTOSAR CAN Network Management (CanNm) Stacks. Das Diagramm spezifiziert die standardisierte 8-Byte-Struktur einer CAN-NM-Botschaft mit Bitpositionen (Bit 7 bis Bit 0) und Byte-Indizes (Byte 0 bis Byte 7).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte 8-Byte-PDU mit folgenden Feldern über die Bitbreite Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\">\n<li><code>Byte 0</code>: Source Node Identifier</li>\n<li><code>Byte 1</code>: Control Bit Vector (CBV)</li>\n<li><code>Byte 2</code>: User data 0</li>\n<li><code>Byte 3</code>: User data 1</li>\n<li><code>Byte 4</code>: PNC bit vector - byte 0</li>\n<li><code>Byte 5</code>: PNC bit vector - byte 1</li>\n<li><code>Byte 6</code>: PNC bit vector - byte 2</li>\n<li><code>Byte 7</code>: PNC bit vector - byte 3</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Frame-Struktur-Definition ohne zeitlichen Ablauf. Bei der zyklischen oder ereignisgesteuerten Übertragung im CanNm wird die PDU von Byte 0 bis Byte 7 serialisiert und an das CAN-Interface (CanIf) übergeben; empfangsseitig parst CanNm Source Node Identifier, Control Bit Vector und extrahiert die Nutzdaten-Bytes 0 bis 5 für höhere Schichten (PduR/Com).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Beispiel-Layout für eine 8-Byte CAN-NM-PDU mit Partial-Networking-Unterstützung (<code>CanNmPnEnabled = TRUE</code>). <code>Byte 0</code> enthält den Source Node Identifier, <code>Byte 1</code> den Control Bit Vector. <code>Byte 2</code> und <code>Byte 3</code> transportieren frei verfügbare Anwenderdaten (<code>User data 0</code> und <code>User data 1</code>), während <code>Byte 4</code> bis <code>Byte 7</code> für den Partial Network Cluster Bit-Vektor (<code>PNC bit vector - byte 0</code> bis <code>byte 3</code>) zur selektiven Aktivierung/Deaktivierung von Teilnetzen reserviert sind.</p>"}], "trans": [{"from": "FIG-28faa903722f3280", "to": "FIG-9968667c45277c6c", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9968667c45277c6c", "to": "FIG-090714385aa958af", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-090714385aa958af", "to": "FIG-13fc0213aa24142b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-13fc0213aa24142b", "to": "FIG-04076bc5501d3fc1", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-04076bc5501d3fc1", "to": "FIG-076c3aa7f24de5b0", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Byte 4 bis Byte 7: Belegung von Nutzdaten („User data 2“ bis „User data 5“) auf Teilnetzvektoren („PNC bit vector - byte 0“ bis „PNC bit vector - byte 3“) geändert.</li>\n</ul>"}, {"from": "FIG-076c3aa7f24de5b0", "to": "FIG-652be64e8790d9a2", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
